def guard(path,sha):
    raw=Path(path).read_bytes()
    assert hashlib.sha1(b"blob "+str(len(raw)).encode()+b"\0"+raw).hexdigest()==sha,path
    return raw
def main():
    p=json.loads(Path("gallery/checkpoints/current.json").read_text())
