    for name,digest in [("gallery/Gallery-current.html","88762177e62e8fd2eeaf4c0016cbf4fb32ecfc0179bd40c53f0df72e52a50250"),("gallery/Gallery-development.html","971d53eacff0274b8403f7224b6096b7d148fd49c7131be019c9613292f28973")]:
        assert hashlib.sha256(Path(name).read_bytes()).hexdigest()==digest,name
    for name,sha,old,new in PATCHES:
        raw=guard(name,sha);old,new=old.encode(),new.encode()
        assert raw==old,name
        Path(name).write_bytes(new)
